function documentHtml(content, assets, viewport = { width: 1200, height: 800 }) {
  const filledCss = replaceAssets(css(assets.fonts), assets);
  const filledContent = replaceAssets(content, assets);
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>${filledCss}</style></head><body style="width:${viewport.width}px;height:${viewport.height}px"><div id="root">${filledContent}</div></body></html>`;
}

